package com.worklink.service;import com.worklink.dto.matching.MatchResult;import com.worklink.entity.*;import com.worklink.entity.enums.ProjectStatus;import com.worklink.exception.*;import com.worklink.repository.*;import com.worklink.security.CurrentUserProvider;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class MatchingService {final ProjectRepository projects;final ClientProfileRepository clients;final FreelancerProfileRepository freelancers;final CurrentUserProvider current;final MatchingScoringService score;public MatchingService(ProjectRepository a,ClientProfileRepository b,FreelancerProfileRepository c,CurrentUserProvider d,MatchingScoringService e){projects=a;clients=b;freelancers=c;current=d;score=e;}@Transactional(readOnly=true) public List<MatchResult> matches(Long id,int limit){ClientProfile c=clients.findByUserId(current.requireCurrentUser().id()).orElseThrow(ProfileNotFoundException::new);Project p=projects.findByIdAndClientId(id,c.getId()).orElseThrow(()->new ResourceNotFoundException("Project not found"));return freelancers.findAll().stream().map(f->score.score(p,f)).sorted(Comparator.comparingDouble(MatchResult::compatibilityScore).reversed()).limit(Math.min(Math.max(limit,1),50)).toList();}@Transactional(readOnly=true) public MatchResult mine(Long id){Project p=projects.findById(id).filter(x->x.getStatus()==ProjectStatus.PUBLISHED).orElseThrow(()->new ResourceNotFoundException("Project not found"));FreelancerProfile f=freelancers.findByUserId(current.requireCurrentUser().id()).orElseThrow(ProfileNotFoundException::new);return score.score(p,f);}}
